#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemm/gemm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GEMM kernel, written in a straightforward way but with
# good row-major access for C and B (j is innermost in the GEMM loop).
@proc
def kernel_gemm(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # Scale C by beta: C = beta * C
    for i in seq(0, ni):
        for j in seq(0, nj):
            C[i, j] = beta * C[i, j]

    # GEMM update: C += alpha * A * B
    # Loop order i-k-j gives contiguous access to rows of B and C.
    for i in seq(0, ni):
        for k in seq(0, nk):
            for j in seq(0, nj):
                C[i, j] += alpha * A[i, k] * B[k, j]


# ---------------------------------------------------------------------------
# Scheduling: cache-friendly tiling + outer parallelism
# ---------------------------------------------------------------------------

# Tile sizes: tuned for typical L1/L2 cache behavior on modern x86.
TI = 32   # tile size in the i (row) dimension
TJ = 32   # tile size in the j (column) dimension

# 1) Tile the i-loop of the scaling phase:
#    for i in 0..ni:
#      for j ...
# becomes
#    for io0 in 0..:
#      for ii0 in 0..TI:
#        for j ...
kernel_gemm = divide_loop(kernel_gemm, "i #0", TI, ["io0", "ii0"])

# 2) Tile the i-loop of the GEMM phase in the same way:
#    the remaining i-loop is now the first (and only) 'i' loop.
kernel_gemm = divide_loop(kernel_gemm, "i #0", TI, ["io1", "ii1"])

# 3) Expose coarse-grain parallelism by parallelizing the outer i-tiles in
#    both phases. The effect analysis guarantees this is race-free.
kernel_gemm = parallelize_loop(kernel_gemm, "io0")
kernel_gemm = parallelize_loop(kernel_gemm, "io1")

# 4) Tile the j-loop (columns) in the scaling phase:
#    for j in 0..nj:
# becomes
#    for jo0 in 0..:
#      for ji0 in 0..TJ:
#        ...
kernel_gemm = divide_loop(kernel_gemm, "j #0", TJ, ["jo0", "ji0"])

# 5) Tile the j-loop in the GEMM phase similarly:
#    after the previous step, the only remaining 'j' loop is in GEMM.
kernel_gemm = divide_loop(kernel_gemm, "j #0", TJ, ["jo1", "ji1"])

# 6) Clean up index arithmetic and dead code introduced by tiling.
kernel_gemm = simplify(kernel_gemm)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_gemm (/*ctxt=*/NULL, ni, nj, nk,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
