from __future__ import annotations

# Core Exo imports.
from exo import *
from exo.libs.memories import DRAM

# Scheduling primitives (loop tiling, parallelization, simplification, ...).
from exo.API_scheduling import *

# ---------------------------------------------------------------------------
# Baseline GEMM kernel:
#
#   C[i, j] = beta * C[i, j] + alpha * sum_{k=0}^{nk-1} A[i, k] * B[k, j]
#
# We keep the object code simple and then apply an explicit schedule below:
#  - tile the i (row) and j (column) loops for cache-blocking,
#  - parallelize the outer i-tiles with OpenMP,
#  - simplify the resulting code.
# ---------------------------------------------------------------------------

