    assert ni >= 1
    assert nj >= 1
    assert nk >= 1

    for i in seq(0, ni):
        # First scale the i-th row of C by beta.
        for j in seq(0, nj):
            C[i, j] = beta * C[i, j]

        # Then accumulate alpha * A[i, k] * B[k, j] into C[i, j].
        #
        # Loop order (i outer, k middle, j inner) yields:
        #   - contiguous accesses to C[i, j] along j,
        #   - contiguous accesses to B[k, j] along j,
        #   - re-use of A[i, k] across all j for a fixed (i, k).
        for k in seq(0, nk):
            for j in seq(0, nj):
                C[i, j] += alpha * A[i, k] * B[k, j]

