#    Each io-iteration updates C[TI*io : TI*(io+1), :] and reads disjoint
#    rows of A, with read-only access to B and scalars alpha/beta, so
#    there are no cross-iteration dependencies.
sched = parallelize_loop(sched, "io")

# 5. Simplify the resulting IR to clean up guards and expressions.
sched = simplify(sched)

# Expose the optimized version under the original name.
kernel_gemm = sched
