from exo.libs.memories import DRAM

# Base GEMM kernel: two-phase (scaling and matrix multiply).
@proc
def kernel_gemm(
    ni: size,
    nj: size,
    nk: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
):
    # Scale C by beta.
    for i in seq(0, ni):
        for j in seq(0, nj):
            C[i, j] = beta * C[i, j]

    # Matrix multiply: C += alpha * A * B in i–k–j order.
    # This order keeps accesses to B[k, j] and C[i, j] contiguous in j,
    # and reuses A[i, k] across the inner j-loop via a_ik.
    for i in seq(0, ni):
        for k in seq(0, nk):
