# 2. Tile the j-loop in the compute phase to improve cache locality
#    for C and B along the contiguous j dimension.
# ---------------------------------------------------------------------------

gemm_opt = kernel_gemm

# Parallelize the scaling loop over i.
scale_i = gemm_opt.find_loop("for i in _:_ #0")
gemm_opt = parallelize_loop(gemm_opt, scale_i)

