Tj = 64
gemm_opt = divide_loop(gemm_opt, compute_j, Tj, ("jo", "ji"), tail="guard")

# Parallelize the outer i-loop of the compute phase.
gemm_opt = parallelize_loop(gemm_opt, compute_i)

# Use the optimized version as the exported kernel.
kernel_gemm = gemm_opt
